  show(){if(!isReady())return;ensureLoaded();if(loaded&&!host.children.length)render();status();},
  async flush(){if(busy)throw Error('请等待性能模型训练完成，或先停止训练。');await queue;if(error.startsWith('未保存'))throw Error(error);},
  reset(){generation++;worker?.cancel();worker?.terminate();worker=null;loaded=false;loading=null;workspace=freshWorkspace();file=null;preview=null;results=[];conditions={};annealChoice='';customAnneal={};formula='';busy=false;error='';trainStatus='';host.replaceChildren();},
